/// <summary>
/// class <c>METTelemetrySOExtractionInfoEvent</c> is used to log event whenever the SO is picked and status is changes to extracted.
/// </summary>
internal final class METTelemetrySOExtractionInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetrySOExtractionInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetrySOExtractionInfoEvent</c> </returns>
public static METTelemetrySOExtractionInfoEvent construct()
{
    return new METTelemetrySOExtractionInfoEvent();
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_salesTable"> instanse of table <c>salesTable</c> </param>
/// <param name = "_metSalesTable"> instanse of table <c>metSalesTable</c> </param>
public void addRunTimePropertyToAppinsights(SalesTable _salesTable)
{
    METSalesTable metSalestable = METSalesTable::findBySalesTable(_salesTable.RecId);

    this.addRuntimeProperty('salesOrderNumber', _salesTable.SalesId);
    this.addRuntimeProperty('warehouseId',_salesTable.InventLocationId);
    this.addRuntimeProperty('orderReferenceNumber', _salesTable.CustomerRef);
    this.addRuntimeProperty('industryKey', metSalestable.IndustryKey);
    this.addRuntimeProperty('metcashSalesOrderType', _salesTable.METSalesOrderType);
    this.addRuntimeProperty('customerNumber', _salesTable.CustAccount);
    this.addRuntimeProperty('transmissionNumber', metSalestable.TransmissionNumber);
}
